R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p; nproc; cat /proc/loadavg
w=sb_mask_carry; mkdir -p $R/$w/in $R/$w/out; echo  | base64 -d | tar xzf - -C $R/$w/in; (cd $R/$w/in && sha256sum -c --quiet SHA256SUMS && echo in OK)
cp $R/sb_cursor_probe/AGENTS.md $R/$w/AGENTS.md; echo  | base64 -d > $R/$w/PROMPT.md
cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; for t in sb_mask_phrase sb_rlfix3 sb_f64fix2; do echo "$t $(wc -c < $R/$t/cursor.log) $(head -c 200 $R/$t/STATUS.md 2>/dev/null)"; done
